module Mcp
  # Runs a tool call (generated by maquina:mcp). Dispatch is an allowlist:
  # public_send only ever reaches a name declared in a visible module's
  # DEFINITIONS, which is what keeps a tool call from being a remote method
  # call. Inside each tool module, helpers are private_class_method.
  #
  # The arguments are checked against the tool's inputSchema first: required
  # keys, unknown keys, the primitive type and enum membership. They reach the
  # tool as keyword arguments.
  module Tools
    InvalidParams = Class.new(StandardError)

    TYPES = {
      "string" => [String],
      "integer" => [Integer],
      "number" => [Integer, Float],
      "boolean" => [TrueClass, FalseClass],
      "array" => [Array],
      "object" => [Hash]
    }.freeze

    # A result Hash for tools/call. Raises InvalidParams for an unknown or
    # hidden tool and for arguments that do not fit the schema.
    def self.call(name, arguments, scope:)
      owner = Mcp::ToolDefinitions.owner(name, scope.user) || raise(InvalidParams, "Unknown tool: #{name}")
      definition = owner::DEFINITIONS.find { |candidate| candidate[:name] == name }

      run(owner, name, scope, validate_arguments(definition[:inputSchema], arguments))
    end

    # Symbol-keyed arguments that fit the schema. A null value counts as not sent.
    def self.validate_arguments(schema, arguments)
      arguments = {} if arguments.nil?
      raise InvalidParams, "arguments must be an object" unless arguments.is_a?(Hash)

      properties = schema.fetch(:properties, {}).transform_keys(&:to_s)
      arguments = arguments.transform_keys(&:to_s).compact

      unknown = arguments.keys - properties.keys
      raise InvalidParams, "Unknown argument: #{unknown.first}" if unknown.any?

      Array(schema[:required]).map(&:to_s).each do |key|
        raise InvalidParams, "Missing required argument: #{key}" unless arguments.key?(key)
      end

      arguments.each { |key, value| check_value(key, properties[key], value) }
      arguments.to_h { |key, value| [key.to_sym, value] }
    end

    def self.check_value(key, property, value)
      type = property[:type].to_s
      if TYPES.key?(type) && TYPES[type].none? { |klass| value.is_a?(klass) }
        raise InvalidParams, "#{key} must be of type #{type}"
      end

      enum = property[:enum]
      raise InvalidParams, "#{key} must be one of: #{enum.join(", ")}" if enum && !enum.include?(value)
    end

    def self.run(owner, name, scope, arguments)
      success(owner.public_send(name, scope: scope, **arguments))
    rescue Mcp::ToolError => error
      failure(error.message)
    rescue ActiveRecord::RecordNotFound
      failure(Mcp::ToolError.not_found.message)
    rescue => error
      # An unexpected failure is still a result the model can read; the
      # details go to the error reporter, not to the client.
      Rails.error.report(error, handled: true, context: {mcp_tool: name})
      failure("#{name} failed on the server. The error was recorded; retrying will not help until it is fixed.")
    end

    def self.success(structured)
      {content: [{type: "text", text: structured.to_json}], structuredContent: structured, isError: false}
    end

    def self.failure(message)
      {content: [{type: "text", text: message}], isError: true}
    end

    private_class_method :check_value, :run, :success, :failure
  end
end
